package io.github.jesterportfolio.hearth.verification;

import java.util.*;import java.util.concurrent.*;import java.nio.file.*;
import org.bukkit.Bukkit;
import io.github.jesterportfolio.hearth.economy.*;
import io.github.jesterportfolio.hearth.survival.SurvivalWorld;
import io.github.jesterportfolio.hearth.survival.platform.*;

/** 실제 소유 Paper/PG의 예약 dispatch·세계 효과·불명 단계 복원. Player 합성 없음. */
public final class JobsVerification {
    private static void check(PlatformRuntime p,boolean ok,String name){if(!ok)throw new IllegalStateException(name);p.plugin.getLogger().info("HEARTH_JOBS_CHECK PASS "+name);}
    public static CompletionStage<Void> run(PlatformRuntime p,String phase){try{
        var root=IsolatedPaths.require(Path.of(System.getProperty("hearth.aura.verification.root","")),"hearth-native-economy-run.");if(!Files.readString(root.resolve(".hearth-aura-isolated")).equals("Hearth AuraSkills isolated v1\n")||!Path.of("").toRealPath().equals(root.resolve("server"))||!Bukkit.getOnlineMode()||!Bukkit.hasWhitelist()||!Bukkit.getIp().equals("127.0.0.1")||!Bukkit.getOnlinePlayers().isEmpty()||!Set.of("prepare","resume","ready").contains(phase))throw new IllegalStateException("JOBS_FIXTURE_GATE");Files.writeString(root.resolve("jobs-"+phase+".started"),"owned localhost zero Players\n",StandardOpenOption.CREATE_NEW);Path expected=root.resolve("jobs-expected.properties");var values=new Properties();
        if(phase.equals("ready")){try(var in=Files.newBufferedReader(expected)){values.load(in);}check(p,p.jobsAllowed()&&!p.jobs.held()&&!p.settings().jobs().enabled(),"final_ready_guard_allows_only_live_platform_without_automatic_jobs");UUID id=UUID.fromString(values.getProperty("unconfirmed"));return p.jobs.inspect(id).thenAcceptAsync(found->{check(p,found.orElseThrow().state()==JobStore.State.SUCCEEDED&&p.resources.active().get(SurvivalWorld.NOVICE).request().equals(id),"final_JAR_restores_reconciled_job_and_world_without_dispatch");},p.owner).thenComposeAsync(v->preserved(p,values),p.owner);}
        if(phase.equals("resume")){try(var in=Files.newBufferedReader(expected)){values.load(in);}UUID id=UUID.fromString(values.getProperty("unconfirmed"));var held=p.jobs.snapshot().active().orElseThrow();check(p,held.id().equals(id)&&held.state()==JobStore.State.HOLD&&held.arguments().get("seed").equals("45"),"new_JVM_restores_unknown_job_as_HOLD_with_fixed_seed");check(p,p.resources.active().get(SurvivalWorld.NOVICE).request().equals(id),"completed_resource_effect_is_restored_before_job_reconciliation");var uuid=p.rpg.runtime.worlds().worlds().get(SurvivalWorld.NOVICE).getUID();return p.jobs.reconcile(id,false).thenComposeAsync(done->{check(p,done.state()==JobStore.State.SUCCEEDED&&p.rpg.runtime.worlds().worlds().get(SurvivalWorld.NOVICE).getUID().equals(uuid),"operator_confirmation_does_not_repeat_world_effect");check(p,!p.jobs.held()&&p.jobs.snapshot().schedules().stream().allMatch(s->s.interval()==0),"paused_schedule_and_completed_history_survive_restart");return p.jobs.inspect(UUID.fromString(values.getProperty("scheduled")));},p.owner).thenAcceptAsync(found->{check(p,found.orElseThrow().scheduled()&&found.orElseThrow().state()==JobStore.State.SUCCEEDED,"scheduled_run_remains_an_immutable_completed_receipt");},p.owner).thenComposeAsync(v->preserved(p,values),p.owner);}
        check(p,p.ready()&&!p.settings().jobs().enabled()&&p.jobs.snapshot().active().isEmpty(),"legacy_platform_starts_without_enabling_jobs");try(var in=Files.newBufferedReader(root.resolve("platform-expected.properties"))){values.load(in);}var old=p.resources.active().get(SurvivalWorld.NOVICE);long generation=old.generation();
        return config(p,true).thenComposeAsync(v->p.rpg.runtime.economy().advanceTick(),p.owner).thenComposeAsync(v->waitScheduled(p),p.owner).thenComposeAsync(job->{check(p,job.scheduled()&&job.state()==JobStore.State.SUCCEEDED,"economic_clock_dispatches_one_persisted_scheduled_job");var active=p.resources.active().get(SurvivalWorld.NOVICE);check(p,active.request().equals(job.id())&&active.seed()==Long.parseLong(job.arguments().get("seed"))&&active.generation()==generation+1,"scheduled_job_id_and_seed_own_actual_new_resource_world");check(p,Bukkit.getWorld(old.world())==null,"scheduled_effect_unloads_previous_generation_without_deleting_it");values.setProperty("scheduled",job.id().toString());return config(p,false);},p.owner).thenComposeAsync(v->{long tick=p.rpg.runtime.economy().logicalTick();return p.jobs.store.reserve(p.rpg.runtime.economy().store.context(p.rpg.runtime.economy().settings.realm(),new UUID(0,0)),UUID.randomUUID(),"resource_reset","end",Map.of("seed","50"),tick,null);},p.owner).thenComposeAsync(reservation->p.jobs.refresh().thenComposeAsync(v->p.jobs.reconcile(reservation.job().id(),true),p.owner),p.owner).thenComposeAsync(cancelled->{check(p,cancelled.state()==JobStore.State.CANCELLED,"operator_can_cancel_proven_not_started_job_without_world_effect");return pendingCancellation(p);},p.owner).thenComposeAsync(v->p.jobs.store.reserve(p.rpg.runtime.economy().store.context(p.rpg.runtime.economy().settings.realm(),new UUID(0,0)),UUID.randomUUID(),"resource_reset","novice",Map.of("seed","45"),p.rpg.runtime.economy().logicalTick(),null),p.owner).thenComposeAsync(reservation->{values.setProperty("unconfirmed",reservation.job().id().toString());return p.resources.reset(SurvivalWorld.NOVICE,45,reservation.job().id());},p.owner).thenComposeAsync(v->p.jobs.refresh(),p.owner).thenAcceptAsync(state->{check(p,state.active().orElseThrow().state()==JobStore.State.RUNNING&&p.resources.active().get(SurvivalWorld.NOVICE).request().toString().equals(values.getProperty("unconfirmed")),"confirmed_effect_and_unconfirmed_job_are_saved_as_separate_checkpoints");try(var out=Files.newBufferedWriter(expected,StandardOpenOption.CREATE_NEW)){values.store(out,"owned job restoration evidence");}catch(Exception e){throw new CompletionException(e);}},p.owner);
    }catch(Exception e){return CompletableFuture.failedFuture(e);}}
    private static CompletionStage<Void> pendingCancellation(PlatformRuntime p){var economy=p.rpg.runtime.economy();UUID request=UUID.randomUUID();var old=p.rpg.runtime.worlds().worlds().get(SurvivalWorld.END);return p.jobs.store.reserve(economy.store.context(economy.settings.realm(),new UUID(0,0)),request,"resource_reset","end",Map.of("seed","51"),economy.logicalTick(),null).thenComposeAsync(v->p.store.reserve(request,"end",old.getUID(),0,51,"NORMAL"),p.owner).thenComposeAsync(v->p.resources.inspect(),p.owner).thenComposeAsync(v->p.jobs.refresh(),p.owner).thenComposeAsync(v->p.jobs.reconcile(request,false).handleAsync((job,error)->{check(p,error!=null,"operator_cannot_confirm_pending_resource_effect");return (Void)null;},p.owner),p.owner).thenComposeAsync(v->p.resources.abort(request),p.owner).thenComposeAsync(v->p.jobs.reconcile(request,true),p.owner).thenAcceptAsync(job->check(p,job.state()==JobStore.State.CANCELLED&&p.rpg.runtime.worlds().worlds().get(SurvivalWorld.END)==old,"explicit_resource_abort_then_job_cancel_preserves_original_world"),p.owner);}
    private static CompletionStage<Void> config(PlatformRuntime p,boolean enabled){try{var data=p.plugin.getDataFolder().toPath();var props=new Properties();try(var in=Files.newBufferedReader(data.resolve("platform.properties"))){props.load(in);}props.setProperty("jobs.enabled",Boolean.toString(enabled));props.setProperty("jobs.resource.novice.interval-ticks",enabled?"1":"0");Path candidate=data.resolve("jobs_trial.candidate");try(var out=Files.newBufferedWriter(candidate,StandardOpenOption.CREATE_NEW)){props.store(out,"fixture-only interval, not selected operating policy");}var plan=p.changes.stage("platform.properties",candidate.getFileName().toString(),p::validateCandidate);return p.apply(plan.id(),false).thenRunAsync(()->{try{Files.delete(candidate);}catch(Exception e){throw new CompletionException(e);}check(p,p.settings().jobs().enabled()==enabled,"canonical_schedule_config_"+(enabled?"enabled":"disabled"));},p.owner);}catch(Exception e){return CompletableFuture.failedFuture(e);}}
    private static CompletionStage<JobStore.Job> waitScheduled(PlatformRuntime p){var result=new CompletableFuture<JobStore.Job>();long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(30);var task=Bukkit.getScheduler().runTaskTimer(p.plugin,()->{if(result.isDone())return;try{if(p.jobs.held()&&!p.jobs.busy())throw new IllegalStateException("JOBS_SCHEDULE_HELD");var done=p.jobs.snapshot().jobs().stream().filter(j->j.scheduled()&&j.state()==JobStore.State.SUCCEEDED).findFirst();if(done.isPresent()&&!p.jobs.busy())result.complete(done.get());else if(System.nanoTime()>deadline)throw new IllegalStateException("JOBS_SCHEDULE_TIMEOUT");}catch(Exception e){result.completeExceptionally(e);}},1,1);result.whenComplete((v,e)->task.cancel());return result;}
    private static CompletionStage<Void> preserved(PlatformRuntime p,Properties values){var economy=p.rpg.runtime.economy();var actor=economy.store.context(economy.settings.realm(),UUID.fromString(values.getProperty("actor")));var sale=economy.store.context(economy.settings.realm(),UUID.fromString(values.getProperty("sale")));return economy.store.account(actor).thenAcceptAsync(account->check(p,EnchantStore.hash(account.inventory().payload()).equals(values.getProperty("upgrade-hash")),"job_recovery_preserves_existing_upgraded_inventory"),p.owner).thenCompose(v->economy.store.account(sale)).thenAcceptAsync(account->check(p,account.balance()==Long.parseLong(values.getProperty("balance"))&&EnchantStore.hash(account.inventory().payload()).equals(values.getProperty("sale-hash")),"job_recovery_preserves_existing_sale_balance_and_items"),p.owner);}
}
